mapper.select:
SELECT M.CO_CD , M.TMPLAT_ID , M.TMPLAT_NM , M.TMPLAT_DIV , NVL(M.DLV_DAYCNT, 0) AS DLV_DAYCNT , NVL(M.RTN_DAYCNT, 0) AS RTN_DAYCNT , M.RMK , NVL(M.USE_YN, 'Y') AS USE_YN , NVL(M.SORT_ORD, 1) AS SORT_ORD , M.CREAT_ID , TO_CHAR(M.CREAT_DTTM, 'YYYY-MM-DD') AS CREAT_DTTM , (SELECT COUNT(*) FROM TB_WB30D01 D WHERE D.CO_CD = M.CO_CD AND D.TMPLAT_ID = M.TMPLAT_ID AND NVL(D.USE_YN, 'Y') = 'Y') AS TASK_CNT FROM TB_WB30M01 M WHERE 1 = 1
AND M.CO_CD = #{coCd}
AND M.USE_YN = #{useYn}
AND (M.TMPLAT_ID LIKE '%' || #{searchValue} || '%' OR M.TMPLAT_NM LIKE '%' || #{searchValue} || '%')
ORDER BY NVL(M.SORT_ORD, 999), M.TMPLAT_ID

mapper.insert:
INSERT INTO TB_WB30M01 (
    CO_CD
  , TMPLAT_ID
  , TMPLAT_NM
  , TMPLAT_DIV
  , DLV_DAYCNT
  , RTN_DAYCNT
  , RMK
  , USE_YN
  , SORT_ORD
  , CREAT_ID
  , CREAT_PGM
  , CREAT_DTTM
) VALUES (
    #{coCd}
  , #{tmplatId}
  , #{tmplatNm}
  , #{tmplatDiv, jdbcType=VARCHAR}
  , #{dlvDaycnt, jdbcType=NUMERIC}
  , #{rtnDaycnt, jdbcType=NUMERIC}
  , #{rmk, jdbcType=VARCHAR}
  , NVL(#{useYn}, 'Y')
  , #{sortOrd, jdbcType=NUMERIC}
  , #{userId}
  , #{pgmId}
  , SYSDATE
)

mapper.update:
UPDATE TB_WB30M01
SET    TMPLAT_NM  = #{tmplatNm}
     , TMPLAT_DIV = #{tmplatDiv, jdbcType=VARCHAR}
     , DLV_DAYCNT = #{dlvDaycnt, jdbcType=NUMERIC}
     , RTN_DAYCNT = #{rtnDaycnt, jdbcType=NUMERIC}
     , RMK        = #{rmk, jdbcType=VARCHAR}
     , USE_YN     = NVL(#{useYn}, 'Y')
     , SORT_ORD   = #{sortOrd, jdbcType=NUMERIC}
     , UDT_ID     = #{userId}
     , UDT_PGM    = #{pgmId}
     , UDT_DTTM   = SYSDATE
WHERE  CO_CD      = #{coCd}
AND    TMPLAT_ID  = #{tmplatId}

mapper.delete:
DELETE FROM TB_WB30M01
WHERE  CO_CD     = #{coCd}
AND    TMPLAT_ID = #{tmplatId}

